        vm.assume(interfaceId != type(IERC1155).interfaceId);
        vm.assume(interfaceId != type(IERC1155MetadataURI).interfaceId);
        bool referenceSupports = c.supportsInterface(interfaceId);
        bool superSupports = ERC165(address(c)).supportsInterface(interfaceId);
        assertTrue(referenceSupports == superSupports);
    }
