// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // 1. No restrict — keep the entire bytes4 domain admissible
        // 2. Call supportsInterface on the deployed contract
        bool result = c.supportsInterface(interfaceId);
        // 3. Assert the rule: if the call claims to support IERC1155 or IERC1155MetadataURI, it MUST also support IERC165
        // This fails on the buggy version when interfaceId is type(IERC1155).interfaceId (and fuzzer will find it)
        if (interfaceId != type(IERC165).interfaceId) {
            vm.assume(result || interfaceId == type(IERC1155).interfaceId || interfaceId == type(IERC1155MetadataURI).interfaceId);
        }
        bool supports1155 = c.supportsInterface(type(IERC1155).interfaceId);
        bool supports1155Metadata = c.supportsInterface(type(IERC1155MetadataURI).interfaceId);
        if (supports1155 || supports1155Metadata) {
            assertTrue(c.supportsInterface(type(IERC165).interfaceId));
        }
    }
}

