import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, uint256 tokenId, uint256 amount) public {
        vm.assume(account != address(0));
        vm.assume(amount > 0);
        vm.assume(tokenId < 1000);
        vm.assume(!c.isAdmin(account));
        vm.prank(address(this));
        c.createGameItem("item", "uri", false, true, 0, 0, 0);
        vm.prank(address(this));
        uint256 itemCount = c.uniqueTokensOutstanding();
        if (tokenId >= itemCount) {
            vm.assume(false);
        }
        vm.prank(address(this));
        c.setAllowedBurningAddresses(address(this));
        vm.prank(address(this));
        c.mint(tokenId, amount);
        uint256 balance = c.balanceOf(account, tokenId);
        assertTrue(balance == amount);
    }
}

